const BEATS={"a1s1":[[2,"Egeon faces the Duke's sentence"],[3,"Syracusans in Ephesus must pay or die"],[6,"Egeon tells of the twins and the shipwreck"],[8,"The family is split in two"],[10,"His son went to find his twin"],[11,"The Duke gives him until sunset"]],"a1s2":[[17,"A merchant warns Antipholus to hide where he is from"],[18,"Dromio takes the money to the Centaur"],[26,"Antipholus feels like a drop lost in the sea"],[29,"The wrong Dromio calls him home to dinner"],[38,"Antipholus demands his thousand marks"],[42,"He beats the bewildered Dromio"],[45,"He fears the town is full of sorcerers"]],"a2s1":[[49,"Adriana waits for her late husband"],[56,"Luciana argues that men are wives' masters"],[63,"Adriana mocks untested patience"],[75,"Dromio reports that his master denied her"],[80,"Adriana beats Dromio and sends him back"],[86,"She fears her husband loves others"],[88,"She remembers the promised chain"]],"a2s2":[[93,"Antipholus finds his gold safe"],[99,"He beats his own Dromio"],[122,"Master and servant joke about time"],[150,"Adriana pleads with the stranger as her husband"],[162,"Antipholus decides to play along"],[164,"Dromio fears they are in fairyland"],[173,"Adriana takes him to dinner and sets Dromio at the gate"]],"a3s1":[[181,"Antipholus of Ephesus comes home with guests"],[193,"Dromio of Syracuse refuses him entry"],[204,"Luce joins the mockery"],[221,"Adriana sends him away"],[237,"He calls for a crowbar"],[240,"Balthasar warns him of scandal"],[241,"He goes to the Courtesan and promises her the chain"]],"a3s2":[[247,"Luciana scolds her 'brother-in-law'"],[248,"He declares his love for her"],[261,"She goes to fetch Adriana"],[269,"Dromio is claimed by the kitchen maid"],[283,"He maps her body like a globe"],[298,"Antipholus sends him to find a ship"],[309,"Angelo hands him the chain"]],"a4s1":[[317,"A merchant demands his money from Angelo"],[321,"Antipholus of Ephesus sends Dromio for a rope"],[332,"He asks Angelo for the chain"],[343,"Each says the other is lying"],[350,"Antipholus is arrested"],[354,"Dromio of Syracuse reports a ship is ready"],[359,"Antipholus sends him for bail money"]],"a4s2":[[365,"Adriana hears that 'her husband' courted Luciana"],[377,"She curses him"],[379,"She admits she still loves him"],[385,"Dromio brings news of the arrest"],[395,"He jokes that time runs backwards"],[401,"Adriana sends the purse"]],"a4s3":[[405,"Everyone in Ephesus seems to know Antipholus"],[407,"Dromio brings him the bail money"],[418,"The Courtesan asks for the chain"],[419,"Antipholus calls her Satan"],[428,"She wants her ring"],[434,"She decides he is mad"]],"a4s4":[[438,"Antipholus of Ephesus waits under arrest"],[443,"Dromio brings a rope instead of money"],[457,"Dromio complains of a lifetime of blows"],[464,"Adriana brings Doctor Pinch"],[469,"Pinch tries to drive out Satan"],[493,"Master and servant are bound"],[521,"Adriana learns of the chain"],[528,"The visitors' drawn swords scatter everyone"],[534,"The travellers decide to leave tonight"]],"a5s1":[[543,"Angelo sees the chain round the wrong neck"],[549,"Antipholus and the merchant draw swords"],[553,"The visitors flee into the priory"],[572,"The Abbess blames Adriana's jealousy"],[594,"Adriana appeals to the Duke"],[597,"News that her husband has escaped"],[614,"Antipholus of Ephesus tells his story"],[620,"The Duke thinks everyone is bewitched"],[642,"Egeon is not recognised by his son"],[650,"The twins are seen together"],[656,"The Abbess reveals she is Emilia"],[677,"The errors are explained"],[695,"The Dromios go in hand in hand"]]};
